@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>Track Your Shipment</h2>

    <div class="row mt-3">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Search
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment == null)
    {
        <div class="alert alert-warning mt-3">
            No shipment found with tracking number "<strong>@searchedNumber</strong>".
        </div>
    }

    @if (shipment != null)
    {
        <div class="card mt-4">
            <div class="card-header">
                <strong>Tracking #@shipment.TrackingNumber</strong>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                            <dt>Estimated Delivery</dt>
                            <dd>@(shipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "Not yet determined")</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isLoading = true;
        searched = true;
        searchedNumber = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingAsync(searchedNumber);
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}

@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-4">
    <h2>Dispatcher Dashboard</h2>

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-primary w-100" @onclick="LoadShipments">
                Refresh
            </button>
        </div>
    </div>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center my-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (filteredShipments.Count == 0)
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Customer</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in filteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                            <td>@s.CustomerEmail</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status" selected="@(status == s.Status)">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<Shipment> shipments = [];
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private bool isLoading = true;

    private List<Shipment> filteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) ||
                    s.Status.ToString() == statusFilter)
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}

